package com.amit.headroom;
import android.content.*;import android.widget.*;import org.json.*;import java.util.*;
public class HeadRoomWidgetService extends RemoteViewsService{public RemoteViewsFactory onGetViewFactory(Intent i){return new Factory(getApplicationContext());}static class Factory implements RemoteViewsFactory{final Context c;JSONArray tasks=new JSONArray();Factory(Context c){this.c=c;}public void onCreate(){}public void onDataSetChanged(){try{String json=c.getSharedPreferences("HeadRoomWidget",MODE_PRIVATE).getString("tasks","[]");tasks=new JSONArray(json);}catch(Exception e){tasks=new JSONArray();}}public void onDestroy(){}public int getCount(){return tasks.length()==0?1:tasks.length();}public RemoteViews getViewAt(int p){try{if(tasks.length()==0){RemoteViews v=new RemoteViews(c.getPackageName(),R.layout.headroom_widget_task);v.setTextViewText(R.id.taskCheck,"✦");v.setTextViewText(R.id.taskTitle,dailyQuote());v.setTextViewText(R.id.taskMeta,"HEADROOM • DAILY NOTE");return v;}JSONObject t=tasks.getJSONObject(p);RemoteViews v=new RemoteViews(c.getPackageName(),R.layout.headroom_widget_task);boolean done=t.optBoolean("done");v.setTextViewText(R.id.taskCheck,done?"✓":"○");v.setTextViewText(R.id.taskTitle,t.optString("text"));String due=t.optString("due");String priority=t.optString("priority","medium").toUpperCase(Locale.ROOT);String tag=t.optString("tag");v.setTextViewText(R.id.taskMeta,(due.isEmpty()?"No due date":due)+"  •  "+priority+(tag.isEmpty()?"":"  •  "+tag));return v;}catch(Exception e){return null;}}private String dailyQuote(){try{java.io.BufferedReader r=new java.io.BufferedReader(new java.io.InputStreamReader(c.getResources().openRawResource(R.raw.motivational_quotes)));java.util.ArrayList<String> q=new java.util.ArrayList<>();String line;while((line=r.readLine())!=null)if(!line.trim().isEmpty())q.add(line);java.time.LocalDate d=java.time.LocalDate.now();return q.get((d.getDayOfYear()-1)%q.size());}catch(Exception e){return "Make room for what matters.";} }public RemoteViews getLoadingView(){return null;}public int getViewTypeCount(){return 1;}public long getItemId(int p){return p;}public boolean hasStableIds(){return false;}}}